package dev.raf.radar;
import android.app.*;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;
final class FriendUi {
 static JSONObject state(Store s){try{return new JSONObject(s.prefs.getString("accountState","{}"));}catch(JSONException e){return new JSONObject();}}
 static int count(Store s){JSONArray a=state(s).optJSONArray("incoming");return a==null?0:a.length();}
 static void badge(MainActivity a){if(a.friendBadge==null)return;int n=count(a.store);a.friendBadge.setText(n>99?"99+":String.valueOf(n));a.friendBadge.setVisibility(n==0?View.GONE:View.VISIBLE);}
 static void controls(MainActivity a){
  TextView add=a.primary("＋ Добавить друга по ID",true,()->add(a));LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,a.dp(44));lp.setMargins(a.dp(16),a.dp(12),a.dp(16),a.dp(8));a.friendsRows.addView(add,lp);
  JSONObject state=state(a.store);requests(a,state.optJSONArray("incoming"),true);requests(a,state.optJSONArray("outgoing"),false);
 }
 static void requests(MainActivity a,JSONArray rows,boolean incoming){if(rows==null)return;for(int i=0;i<rows.length();i++)try{JSONObject p=rows.getJSONObject(i);int id=p.getInt("id");String name=p.optString("name","");if(name.isEmpty())name="Пользователь";String label=incoming?"Вас хочет добавить в друзья "+name+" · ID "+id:"Запрос отправлен: "+name+" · ID "+id;TextView request=a.primary(label,false,()->{AlertDialog.Builder b=new AlertDialog.Builder(a).setTitle(label).setNegativeButton(incoming?"Отклонить":"Закрыть",(d,w)->{if(incoming)command(a,"reject",id);});if(incoming)b.setPositiveButton("Принять",(d,w)->command(a,"accept",id));else b.setPositiveButton("Отменить запрос",(d,w)->command(a,"cancel",id));b.show();});request.setContentDescription(label);request.setPadding(a.dp(16),a.dp(10),a.dp(16),a.dp(10));a.friendsRows.addView(request,new LinearLayout.LayoutParams(-1,-2));}catch(JSONException ignored){}}
 static void add(MainActivity a){EditText input=new EditText(a);input.setHint("ID 1–999");input.setInputType(InputType.TYPE_CLASS_NUMBER);input.setFilters(new android.text.InputFilter[]{new android.text.InputFilter.LengthFilter(3)});LinearLayout box=a.column();box.setPadding(a.dp(20),0,a.dp(20),0);box.addView(input);AlertDialog dialog=new AlertDialog.Builder(a).setTitle("Добавить друга по ID").setView(box).setNegativeButton("Отмена",null).setPositiveButton("Отправить запрос",null).create();dialog.show();dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String raw=input.getText().toString();if(raw.isEmpty()||Integer.parseInt(raw)<1){input.setError("ID от 1 до 999");return;}int id=Integer.parseInt(raw);if(id==a.store.prefs.getInt("accountId",0)){input.setError("Нельзя добавить себя");return;}dialog.dismiss();command(a,"request",id);});}
 static void command(MainActivity a,String action,int id){if(a.socialPending)return;a.socialPending=true;JSONObject body=AccountClient.action(action);try{body.put("target",id);}catch(JSONException e){throw new IllegalStateException(e);}AccountClient.call(a,body,(data,error)->{a.socialPending=false;if(a.isDestroyed())return;if(error!=null){a.toast(error);return;}a.friends=AccountClient.peers(data);a.peers=new java.util.ArrayList<>(a.friends);a.pointOverlay.invalidate();a.directoryError=false;a.renderFriends();badge(a);});}
 static void remove(MainActivity a,PresenceClient.Peer p){new AlertDialog.Builder(a).setTitle("Удалить из друзей: "+p.name+"?").setMessage("Доступ к последним координатам друг друга будет закрыт.").setNegativeButton("Отмена",null).setPositiveButton("Удалить",(d,w)->command(a,"remove",Integer.parseInt(p.id))).show();}
}
